import{_ as n,o as a,c as o,a7 as t}from"./chunks/framework.SuvwUnl3.js";const c=JSON.parse('{"title":"Plugins","description":"How to install and update Axolotl-PM plugins from .phar files, and where to start if you want to write your own.","frontmatter":{"title":"Plugins","outline":"deep","description":"How to install and update Axolotl-PM plugins from .phar files, and where to start if you want to write your own.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/plugins"}]]},"headers":[],"relativePath":"docs/plugins.md","filePath":"docs/plugins.md","lastUpdated":1790689997000}'),i={name:"docs/plugins.md"};function l(s,e,r,p,u,d){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h1><p>Axolotl-PM can be extended and customized with plugins.</p><p>A plugin is an external module which can be “plugged in” to your server to add custom features, change default behaviours and more.</p><h2 id="downloading-plugins" tabindex="-1">Downloading plugins <a class="header-anchor" href="#downloading-plugins" aria-label="Permalink to &quot;Downloading plugins&quot;">​</a></h2><p>You can find a wide range of premade plugins on the <a href="https://poggit.pmmp.io/plugins" target="_blank" rel="noreferrer">Poggit Release</a> plugin platform.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Poggit is now read-only. Existing plugins can still be found there, but no new plugins or updates are being published.</p></div><h2 id="installing-updating-a-plugin" tabindex="-1">Installing/updating a plugin <a class="header-anchor" href="#installing-updating-a-plugin" aria-label="Permalink to &quot;Installing/updating a plugin&quot;">​</a></h2><p>Plugin developers usually distribute plugins as <a href="http://php.net/manual/en/phar.using.intro.php" target="_blank" rel="noreferrer">phar</a> files. These files can be easily loaded by placing them in your <code>plugins</code> folder in the server data folder.</p><p>Be sure to <strong>delete old versions of the plugin</strong>, and <strong>restart the server</strong> to see changes.</p><h2 id="writing-your-own-plugins" tabindex="-1">Writing your own plugins <a class="header-anchor" href="#writing-your-own-plugins" aria-label="Permalink to &quot;Writing your own plugins&quot;">​</a></h2><p>You can find resources for plugin development in the <a href="/website/previews/64a4d62da9a7/docs/developers/plugin-docs-index">plugin development docs</a> section.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>All public plugins on Poggit Release are open-source, and there are many more on GitHub.</p><p>You can learn a lot from looking at other people’s code that you can’t easily learn from documentation pages.</p></div>',12)])])}const h=n(i,[["render",l]]);export{c as __pageData,h as default};
